inline std::optional<BoardCells> to_board(const Piece& piece) noexcept {
    BoardCells candidate{};
    for (std::size_t i = 0; i < piece.local.size(); ++i) {
        const std::int64_t row =
            static_cast<std::int64_t>(piece.local[i].row) +
            static_cast<std::int64_t>(piece.origin.row);
        const std::int64_t column =
            static_cast<std::int64_t>(piece.local[i].column) +
            static_cast<std::int64_t>(piece.origin.column);
        if (row < std::numeric_limits<int>::min() ||
            row > std::numeric_limits<int>::max() ||
            column < std::numeric_limits<int>::min() ||
            column > std::numeric_limits<int>::max()) {
            return std::nullopt;
        }
        candidate[i] = study_grid::Position{
            static_cast<int>(row), static_cast<int>(column)};
    }
    return candidate;
}

struct Mesh {
    std::array<study_mesh::Vertex2,24> vertices{};
    std::size_t count=0; // Used prefix only; invisible cells do not submit zeros.
};
// Visual filtering only: out-of-board cells are omitted, not clamped or moved.
// This function knows no Grid occupancy and is NOT collision validation.
inline Mesh make_visible_mesh(const study_piece::BoardCells& cells) noexcept {
    Mesh mesh{};
    for(const auto cell:cells){
        const auto rect=study_board::cell_rect(cell.row,cell.column);
        if(!rect)continue;
        for(const auto vertex:study_board::quad_vertices(*rect))
            mesh.vertices[mesh.count++]=vertex;
    }
    return mesh;
}

inline std::array<study_mesh::Vertex2,6> quad_vertices(const Rect& r) noexcept {
    const double corners[6][2] = {
        {r.left,r.bottom},{r.right,r.bottom},{r.right,r.top},
        {r.left,r.bottom},{r.right,r.top},{r.left,r.top}
    };
    std::array<study_mesh::Vertex2,6> vertices{};
    for(std::size_t i=0;i<vertices.size();++i){
        const auto clip=study_coordinates::ui_to_clip(
            corners[i][0],corners[i][1],logical_width,logical_height);
        vertices[i]={static_cast<float>(clip->x),static_cast<float>(clip->y)};
    }
    return vertices;
}

inline constexpr char fragment[] = R"glsl(#version 330 core
layout(location = 0) out vec4 out_color;
void main() { out_color = vec4(0,0.75,1,1); }
)glsl";
// Borrow the board pass's viewport/scissor/opaque state. Never clear here.
// available matches the uploaded used prefix. Zero means no GL objects needed.
inline bool render(const study_gl::GlApi& gl,study_gl::GLuint program,
                   study_gl::GLuint vao,study_gl::GLsizei available) noexcept {
    if(available<0 || available>24 || available%6!=0)return false;
    if(available==0)return true;
    return study_gl::submit_triangles(gl,program,vao,available,0,available);
}
